system {
    host-name LAB-MX-1;
    time-zone some/time;
    default-address-selection;
    no-redirects;
    no-ping-record-route;
    no-ping-time-stamp;
    tacplus-server {
        1.1.1.1 {
            port 49;
            secret "<SECRET_HASH>"; ## SECRET-DATA
            source-address 5.5.5.5;
        }
        2.2.2.2 {
            port 49;
            secret "<SECRET_HASH>"; ## SECRET-DATA
            source-address 5.5.5.5;
        }
        4.4.4.4 {
            port 49;
            secret "<SECRET_HASH>"; ## SECRET-DATA
            source-address 5.5.5.5;
        }
    }
    services {
        ssh {
            root-login deny;
            no-tcp-forwarding;
            protocol-version v2;
            max-sessions-per-connection 32;
            client-alive-count-max 3;
            client-alive-interval 10;
            connection-limit 10;
            rate-limit 5;
        }
        netconf {
            ssh {
                connection-limit 10;
                rate-limit 4;
            }
        }
    }
}
